<?php
require __DIR__ . '/../src/bootstrap.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';$method=$_SERVER['REQUEST_METHOD'];
if(!str_starts_with($path,'/api/')){readfile(__DIR__.'/app.html');exit;}
$data=store();$u=user();$body=json_input();
if($path==='/api/auth/register'&&$method==='POST'){if(strlen(trim((string)($body['username']??'')))<3||strlen((string)($body['password']??''))<6)respond(['error'=>'Tài khoản tối thiểu 3 ký tự, mật khẩu tối thiểu 6 ký tự'],422);foreach($data['users'] as $x)if($x['username']===$body['username'])respond(['error'=>'Tên tài khoản đã tồn tại'],409);$id=next_id($data['users']);$data['users'][]=['id'=>$id,'name'=>trim((string)($body['name']??'Người dùng')),'username'=>trim((string)$body['username']),'password_hash'=>password_hash((string)$body['password'],PASSWORD_DEFAULT)];save_store($data);$_SESSION['user_id']=$id;respond(['user'=>user()]);}
if($path==='/api/auth/login'&&$method==='POST'){foreach($data['users'] as $x)if($x['username']===$body['username']&&password_verify((string)($body['password']??''),$x['password_hash'])){$_SESSION['user_id']=$x['id'];respond(['user'=>user()]);}respond(['error'=>'Sai tài khoản hoặc mật khẩu'],422);}
if($path==='/api/auth/logout'&&$method==='POST'){session_destroy();respond(['ok'=>true]);}if($path==='/api/auth/me')respond(['user'=>$u]);if(!$u)respond(['error'=>'Bạn cần đăng nhập'],401);
if($path==='/api/exams'&&$method==='GET')respond(array_values(array_filter($data['exams'],fn($e)=>$e['user_id']===$u['id'])));
if($path==='/api/exams'&&$method==='POST'){$codes=array_values(array_filter(array_map('trim',(array)($body['codes']??['101']))));$id=next_id($data['exams']);$e=['id'=>$id,'user_id'=>$u['id'],'name'=>trim((string)($body['name']??'Bài thi mới')),'subject'=>trim((string)($body['subject']??'Trắc nghiệm')),'question_count'=>max(1,min(200,(int)($body['question_count']??40))),'codes'=>$codes];$data['exams'][]=$e;foreach($codes as $code)$data['keys'][]=['id'=>next_id($data['keys']),'exam_id'=>$id,'code'=>$code,'answers'=>str_repeat('-',$e['question_count'])];save_store($data);respond(['id'=>$id],201);}
if(preg_match('#^/api/exams/(\d+)$#',$path,$m)&&$method==='GET'){$id=(int)$m[1];$e=null;foreach($data['exams'] as $x)if($x['id']===$id&&$x['user_id']===$u['id'])$e=$x;if(!$e)respond(['error'=>'Không tìm thấy bài thi'],404);$e['keys']=array_values(array_filter($data['keys'],fn($k)=>$k['exam_id']===$id));$e['students']=array_values(array_filter($data['students'],fn($s)=>$s['exam_id']===$id));respond($e);}
if(preg_match('#^/api/exams/(\d+)/keys$#',$path,$m)&&$method==='PUT'){foreach((array)($body['keys']??[]) as $k)foreach($data['keys'] as &$x)if($x['exam_id']==(int)$m[1]&&$x['code']===$k['code'])$x['answers']=$k['answers'];unset($x);save_store($data);respond(['ok'=>true]);}
if(preg_match('#^/api/exams/(\d+)/students$#',$path,$m)&&$method==='POST'){$id=(int)$m[1];foreach((array)($body['students']??[]) as $s){$found=false;foreach($data['students'] as &$x)if($x['exam_id']===$id&&$x['student_no']===$s['student_no']){$x['name']=$s['name'];$x['class_name']=$s['class_name']??'';$found=true;}unset($x);if(!$found)$data['students'][]=['id'=>next_id($data['students']),'exam_id'=>$id,'student_no'=>$s['student_no'],'name'=>$s['name'],'class_name'=>$s['class_name']??''];}save_store($data);respond(['ok'=>true]);}
if(preg_match('#^/api/exams/(\d+)/submissions$#',$path,$m)&&$method==='POST'){$id=(int)$m[1];$code=(string)($body['code']??'101');$key='';foreach($data['keys'] as $k)if($k['exam_id']===$id&&$k['code']===$code)$key=$k['answers'];if($key==='')respond(['error'=>'Chưa có đáp án cho mã đề'],422);$answers=(string)($body['answers']??'');$score=0;$flags=[];for($i=0;$i<strlen($key);$i++){ $a=$answers[$i]??'-';$b=$key[$i]??'-';if($a==='-'||$a==='')$flags[]='Câu '.($i+1).' bỏ trống';elseif($a===$b)$score++;elseif($a==='?')$flags[]='Câu '.($i+1).' cần kiểm tra';}$score=round($score*10/max(1,strlen($key)),2);$row=['id'=>next_id($data['submissions']),'exam_id'=>$id,'student_no'=>(string)($body['student_no']??''),'student_name'=>(string)($body['student_name']??''),'code'=>$code,'answers'=>$answers,'score'=>$score,'flags'=>$flags,'image_data'=>$body['image_data']??null,'created_at'=>date('c')];$data['submissions'][]=$row;save_store($data);respond(['id'=>$row['id'],'score'=>$score,'flags'=>$flags],201);}
if(preg_match('#^/api/exams/(\d+)/results$#',$path,$m)&&$method==='GET')respond(array_values(array_filter($data['submissions'],fn($s)=>$s['exam_id']==(int)$m[1])));
if(preg_match('#^/api/exams/(\d+)/export$#',$path,$m)&&$method==='GET'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="bang-diem.csv"');echo "\xEF\xBB\xBFSTT,So bao danh,Ho ten,Ma de,Dap an,Diem,Canh bao,Thoi gian\n";$i=1;foreach(array_filter($data['submissions'],fn($s)=>$s['exam_id']==(int)$m[1]) as $r)echo $i++.','.implode(',',array_map(fn($v)=>'"'.str_replace('"','""',(string)$v).'"',[$r['student_no'],$r['student_name'],$r['code'],$r['answers'],$r['score'],implode('; ',$r['flags']),$r['created_at']]))."\n";exit;}
respond(['error'=>'API không tồn tại'],404);

